package com.medtrack.transfer.entity; import com.medtrack.shared.model.BaseEntity; import com.medtrack.user.entity.User; import com.medtrack.warehouse.entity.Warehouse; import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="stock_transfers") public class StockTransfer extends BaseEntity {@Column(name="transfer_number",nullable=false,unique=true)private String transferNumber;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="source_warehouse_id",nullable=false)private Warehouse sourceWarehouse;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="destination_warehouse_id",nullable=false)private Warehouse destinationWarehouse;@Enumerated(EnumType.STRING)@Column(nullable=false)private TransferStatus status;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="requested_by",nullable=false)private User requestedBy;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="approved_by")private User approvedBy;private String notes;@OneToMany(mappedBy="transfer",cascade=CascadeType.ALL,orphanRemoval=true)private List<StockTransferItem> items=new ArrayList<>();protected StockTransfer(){}public StockTransfer(String number,Warehouse source,Warehouse destination,User user,String notes){transferNumber=number;sourceWarehouse=source;destinationWarehouse=destination;requestedBy=user;this.notes=notes;status=TransferStatus.REQUESTED;}public void addItem(StockTransferItem i){i.setTransfer(this);items.add(i);}public void transition(TransferStatus next){TransferStateMachine.assertAllowed(status,next);status=next;}public void approve(User user){approvedBy=user;transition(TransferStatus.APPROVED);}public UUID getId(){return super.getId();}public String getTransferNumber(){return transferNumber;}public Warehouse getSourceWarehouse(){return sourceWarehouse;}public Warehouse getDestinationWarehouse(){return destinationWarehouse;}public TransferStatus getStatus(){return status;}public List<StockTransferItem>getItems(){return items;}public User getRequestedBy(){return requestedBy;}}
